xql_query:
// ============================================================
// Rule: GIT_Public Repository Created
// Vendor: GIT
// Objective:
// Detect activity associated with GIT_Public Repository Created.
// Severity: SEV_040_HIGH
// Category: EXFILTRATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0010 - Exfiltration
// Technique: T1567 - Exfiltration Over Web Service
// Technique: T1567.001 - Exfiltration Over Web Service: Exfiltration to Code Repository

// Fonte de dados: logs brutos do GitHub
dataset = github_github_raw  

// Filtra apenas eventos onde a ação seja "created"
// (ou seja, criação de um novo repositório)
| filter action = "created"  

// Cria campos derivados para facilitar a análise
| alter
    user = sender -> login,                   // Usuário que criou o repositório
    enterprise_name = enterprise -> name,     // Nome da organização/enterprise
    git_url = repository -> git_url,          // URL do repositório criado
    private = repository -> private,          // Indica se o repositório é privado ou público
    description = repository -> description   // Descrição fornecida para o repositório

// Mantém apenas os repositórios criados como públicos
| filter private != "true"  

// Seleção dos campos principais para exibição
| fields user, enterprise_name, git_url, private
